private final class LinkMoveGate:@unchecked Sendable{let condition=NSCondition();var ready=false;func wait(){condition.lock();while !ready{condition.wait()};condition.unlock()};func release(){condition.lock();ready=true;condition.broadcast();condition.unlock()}}
