  func fixture(_ depth:PixelDepth = .u8)throws->CraftDocument{var d=try LayerCollectionTransformWorkflowTests().fixture(depth);try Command.layerLinks(.link(d.layers.map(\.id))).apply(to:&d);d.activeLayerID=d.layers[0].id;return d}
