  @MainActor func testLinkedFreeTransformCapturesRawTargetsPreviewAndCommitSelectionGuard()async throws{
    let source=try fixture(),s=store(source);defer{s.cancelTransform();s.renderTask?.cancel()};s.beginTransform();let draft=try XCTUnwrap(s.transformDraft),session=try XCTUnwrap(s.selectionTransform);XCTAssertEqual(draft.collectionLayerIDs,source.layers.map(\.id));XCTAssertEqual(draft.collectionViewIDs,[source.layers[0].id]);s.updateTransform(draft.selectionApplying(.translation(4,3)));await SelectedPixelTransformWorkflowTests().settle(session);XCTAssertNotNil(session.pixelPreview);XCTAssertEqual(s.document,source);s.commitTransform();await session.commitTask?.value;XCTAssertNil(session.error);var expected=source;try Command.transformLayers(.init(layerIDs:[source.layers[0].id],matrix:.translation(4,3))).apply(to:&expected);XCTAssertEqual(s.document,expected);_=await s.requestHistory(redo:false).value;XCTAssertEqual(s.document,source);s.beginTransform();let changed=try XCTUnwrap(s.selectionTransform);s.selectedLayerIDs=[source.layers[1].id];s.commitTransform();await changed.commitTask?.value;XCTAssertNotNil(changed.error);XCTAssertEqual(s.document,source)
