  @MainActor func testActualNoSelectionCanvasMoveAndOptionCopyCommitOneUndo()async throws{
    _=NSApplication.shared;let h=SelectedPixelMoveWorkflowTests();for copy in [false,true]{let source=try fixture(),s=store(source);s.zoom=8;let canvas=CraftCanvas(store:s),window=NSWindow(contentRect:.init(x:0,y:0,width:400,height:300),styleMask:.borderless,backing:.buffered,defer:false);window.isReleasedWhenClosed=false;window.contentView=canvas;canvas.frame=window.contentView!.bounds;canvas.synchronizeViewport();defer{s.cancelTransform();s.renderTask?.cancel();window.contentView=nil;window.close()};let start=CGPoint(x:5,y:6),end=CGPoint(x:9,y:9);canvas.mouseDown(with:h.mouse(.leftMouseDown,start,canvas:canvas,window:window,flags:copy ? .option:[]));let session=try XCTUnwrap(s.selectionTransform);XCTAssertEqual(s.transformDraft?.movingLayers,true);canvas.mouseDragged(with:h.mouse(.leftMouseDragged,end,canvas:canvas,window:window));XCTAssertEqual(s.document,source);XCTAssertEqual(canvas.toolCursor,.selectedPixels(copy:copy,constrained:false,unsnapped:false));canvas.mouseUp(with:h.mouse(.leftMouseUp,end,canvas:canvas,window:window));await session.commitTask?.value;XCTAssertNil(session.error);XCTAssertNil(s.error);XCTAssertEqual(s.session.undoStack.count,1);if !copy{var expected=source;try Command.moveLayers(.init(layerIDs:[source.layers[0].id],dx:4,dy:3)).apply(to:&expected);XCTAssertEqual(s.document,expected)}else{XCTAssertEqual(s.document.layers.count,4);for layer in source.layers{XCTAssertEqual(s.document.layers.first{$0.id==layer.id},layer)};let new=s.document.layers.filter{!source.layers.map(\.id).contains($0.id)};XCTAssertEqual(s.selectedLayerIDs,Set(new.map(\.id)));XCTAssertEqual(new[0].linkID,new[1].linkID);XCTAssertNotEqual(new[0].linkID,source.layers[0].linkID)};_=await s.requestHistory(redo:false).value;XCTAssertEqual(s.document,source)}
  }
  @MainActor func testAll16WholeMoveAndLinkCursorsCapturedCopyConstraintAndNudges()async throws{
    let source=try fixture(),s=store(source),canvas=CraftCanvas(store:s);defer{s.cancelTransform();s.renderTask?.cancel()};s.snappingEnabled=true;s.snapToGuides=true;let flags:[NSEvent.ModifierFlags]=[.control,.command,.option,.shift];for bits in 0..<16{let f=flags.enumerated().reduce(NSEvent.ModifierFlags()){r,p in bits&(1<<p.offset) != 0 ? r.union(p.element):r};canvas.updateCursorModifiers(f);XCTAssertEqual(canvas.toolCursor,.selectedPixels(copy:bits&4 != 0,constrained:bits&8 != 0,unsnapped:bits&10 != 0));XCTAssertTrue(s.beginWholeLayerMove(modifiers:f));canvas.updateCursorModifiers([]);XCTAssertEqual(canvas.toolCursor,.selectedPixels(copy:bits&4 != 0,constrained:false,unsnapped:false));XCTAssertEqual(ToolCursor.layerLink(modifiers:f,linked:true,disabled:false,available:true),.symbol("link",.subtract));XCTAssertEqual(ToolCursor.layerLink(modifiers:f,linked:true,disabled:true,available:true),.symbol("link",bits&8 != 0 ? .add:.subtract));s.cancelTransform()};s.snappingEnabled=false;XCTAssertTrue(s.beginWholeLayerMove(modifiers:.option));let draft=try XCTUnwrap(s.transformDraft);s.updateWholeLayerMove(draft,from:.zero,to:.init(x:10,y:6),modifiers:.shift,zoom:1);XCTAssertEqual(s.transformDraft?.moveOffsetX,8);XCTAssertEqual(s.transformDraft?.moveOffsetY,8);XCTAssertEqual(s.transformDraft?.copyWholeLayers,true);s.cancelTransform();XCTAssertTrue(s.nudgeWholeLayers(keyCode:124,modifiers:.shift));await s.geometryTask?.value;XCTAssertEqual(s.document.layers[0].x,source.layers[0].x+10);XCTAssertEqual(s.document.layers[1].x,source.layers[1].x+10);XCTAssertFalse(s.nudgeWholeLayers(keyCode:124,modifiers:.command));XCTAssertFalse(s.nudgeWholeLayers(keyCode:124,modifiers:.control))
  }
  @MainActor func testHTTPLinkAndMoveDepthProfilesNativeBytesActions39And40()async throws{
    let h=AutomationTests();try await h.withService(pressedMouseButtons:{0}){service,doc in let s=doc.store;for depth in PixelDepth.allCases{var source=try LayerCollectionTransformWorkflowTests().fixture(depth);source.workingICC=try ColorManagement.importedProfile(XCTUnwrap(CGColorSpace(name:CGColorSpace.displayP3)?.copyICCData() as Data?),depth:depth);s.session=EditorSession(document:source);s.selectedLayerIDs=[source.layers[0].id];try service.share(doc);try s.session.startActionRecording(name:"Links and Move");let ids=source.layers.map(\.id);var expected=source;let link=try await h.edit(service,doc,"layer.links",["layerIDs":ids.map(\.uuidString),"operation":"link"]);XCTAssertEqual(link,200);try Command.layerLinks(.link(ids)).apply(to:&expected);XCTAssertEqual(s.document,expected);var file=ActionLibraryFile();file.actions=[try XCTUnwrap(s.session.actionRecording?.snapshot)];XCTAssertEqual(try ActionLibraryFile.decode(file.encoded()).version,39);let linked=s.document,count=s.session.undoStack.count;let select=try await h.edit(service,doc,"layer.links",["layerIDs":[ids[0].uuidString],"operation":"select"]);XCTAssertEqual(select,200);XCTAssertEqual(s.document,linked);XCTAssertEqual(s.session.undoStack.count,count);let move=try await h.edit(service,doc,"layers.move",["layerIDs":[ids[0].uuidString],"dx":4,"dy":3]);XCTAssertEqual(move,200);try Command.moveLayers(.init(layerIDs:[ids[0]],dx:4,dy:3)).apply(to:&expected);XCTAssertEqual(s.document,expected);XCTAssertEqual(try NativeArchive.encodeChunked(s.document),try NativeArchive.encodeChunked(expected));file.actions=[try XCTUnwrap(s.session.actionRecording?.snapshot)];let bytes=try file.encoded();XCTAssertEqual(try ActionLibraryFile.decode(bytes).version,40);var wrong=try XCTUnwrap(JSONSerialization.jsonObject(with:bytes) as? [String:Any]);wrong["version"]=39;XCTAssertThrowsError(try ActionLibraryFile.decode(JSONSerialization.data(withJSONObject:wrong)));var replay=source;try file.actions[0].apply(to:&replay);XCTAssertEqual(replay,s.document);_=await s.requestHistory(redo:false).value;XCTAssertEqual(s.document,linked)}}
  }
  @MainActor func testInvalidBusyStaleRevokedCancelledAndLockedMovesAreAtomic()async throws{
    let h=AutomationTests();try await h.withService(pressedMouseButtons:{0}){service,doc in let source=try self.fixture(),s=doc.store;s.session=EditorSession(document:source);s.selectedLayerIDs=[source.layers[0].id];try service.share(doc);let params:[String:Any]=["layerIDs":[source.layers[0].id.uuidString],"dx":3,"dy":2];for extra:[String:Any] in [["layerIDs":[]],["layerIDs":["bad"]],["layerIDs":[source.layers[0].id.uuidString,source.layers[0].id.uuidString]],["dx":1_000_001],["dx":0.5],["copy":"yes"],["unknown":1]]{let code=try await h.edit(service,doc,"layers.move",params.merging(extra){_,b in b});XCTAssertEqual(code,400);XCTAssertEqual(s.document,source)};let unknown=try await h.edit(service,doc,"layers.move",params.merging(["layerIDs":[UUID().uuidString]]){_,b in b});XCTAssertEqual(unknown,404);let stale=try await h.edit(service,doc,"layers.move",params,revision:"old");XCTAssertEqual(stale,409);XCTAssertTrue(s.beginWholeLayerMove(modifiers:[]));let busy=try await h.edit(service,doc,"layers.move",params);XCTAssertEqual(busy,409);s.cancelTransform();var locked=source;locked.layers[1].protection = .position;s.session=EditorSession(document:locked);let code=try await h.edit(service,doc,"layers.move",params);XCTAssertEqual(code,422);XCTAssertEqual(s.document,locked);s.error=nil;s.session=EditorSession(document:source);let gate=LinkMoveGate();defer{gate.release()};s.wholeLayerMovePreparation={_,r in gate.wait();try Task.checkCancellation();return .moveLayers(r)};let task=Task{try await h.edit(service,doc,"layers.move",params)};let until=Date().addingTimeInterval(10);while !s.geometryBusy && Date()<until{await Task.yield()};service.revoke(try XCTUnwrap(service.shares.first?.id));gate.release();let revoked=try await task.value;XCTAssertEqual(revoked,409);XCTAssertEqual(s.document,source);let native=LinkMoveGate();defer{native.release()};s.wholeLayerMovePreparation={_,r in native.wait();try Task.checkCancellation();return .moveLayers(r)};XCTAssertTrue(s.beginWholeLayerMove(modifiers:.option));let session=try XCTUnwrap(s.selectionTransform);s.commitTransform();s.cancelTransform();native.release();await session.commitTask?.value;XCTAssertEqual(s.document,source)}
  }
  @MainActor func testMoveReadFocusToolCloseAndBoundedPreviewLifecycle()async throws{
    var source=try fixture();try Command.imageSize(4096,3072,source.pixelsPerInch,.nearest).apply(to:&source);let doc=CraftNSDocument(model:source),s=doc.store;s.tool = .move;s.selectedLayerIDs=[source.layers[0].id];defer{s.cancelTransform();s.renderTask?.cancel();doc.updateChangeCount(.changeCleared);doc.close()};XCTAssertTrue(s.beginWholeLayerMove(modifiers:.option));let session=try XCTUnwrap(s.selectionTransform),draft=try XCTUnwrap(s.transformDraft);for i in 1...20{s.updateWholeLayerMove(draft,from:.zero,to:.init(x:i,y:i),modifiers:[],zoom:1)};await SelectedPixelTransformWorkflowTests().settle(session);XCTAssertNotNil(session.pixelPreview);XCTAssertEqual(session.pixelPreview?.image.width,1024);XCTAssertEqual(s.document,source);XCTAssertTrue(s.session.undoStack.isEmpty);try doc.read(from:NativeArchive.encodeChunked(source),ofType:CraftNSDocument.nativeType);XCTAssertTrue(session.closed);s.selectedLayerIDs=[source.layers[0].id];let canvas=CraftCanvas(store:s),window=NSWindow(contentRect:.init(x:0,y:0,width:200,height:150),styleMask:.borderless,backing:.buffered,defer:false);window.isReleasedWhenClosed=false;window.contentView=canvas;defer{window.contentView=nil;window.close()};XCTAssertTrue(s.beginWholeLayerMove(modifiers:[]));NotificationCenter.default.post(name:NSWindow.didResignKeyNotification,object:window);XCTAssertNil(s.transformDraft);XCTAssertTrue(s.beginWholeLayerMove(modifiers:[]));s.tool = .brush;canvas.synchronizeTool();XCTAssertNil(s.transformDraft);s.tool = .move;XCTAssertTrue(s.beginWholeLayerMove(modifiers:[]));let closing=try XCTUnwrap(s.selectionTransform);doc.close();XCTAssertTrue(closing.closed)
  }
  func testOwnedMoveCopyOutputsCapturedForIndependentRGBAReader()throws{
    var rows:[[String:Any]]=[];for disabled in [false,true]{for copy in [false,true]{for offset in [(5,3),(-2,-1)]{var d=try CraftDocument(width:20,height:16),a=Layer(name:"A",content:.raster(try Surface(width:3,height:2,fill:Pixel(1,0,0)))),b=Layer(name:"B",content:.raster(try Surface(width:4,height:3,fill:Pixel(0,0,1))));a.x=2;a.y=3;b.x=9;b.y=6;d.layers=[a,b];d.activeLayerID=a.id;try Command.layerLinks(.link([a.id,b.id])).apply(to:&d);if disabled{try Command.layerLinks(.enabled([b.id],false)).apply(to:&d)};try Command.moveLayers(.init(layerIDs:[a.id],dx:offset.0,dy:offset.1,copy:copy)).apply(to:&d);let out=try Renderer.render(d).surface;var rgba:[Int]=[];for y in 0..<16{for x in 0..<20{let p=out.pixel(x:x,y:y);rgba += [p.r,p.g,p.b,p.a].map{Int((unit($0)*255).rounded())}}};rows.append(["dx":offset.0,"dy":offset.1,"disabledB":disabled,"copy":copy,"rgba":rgba])}}};if let path=ProcessInfo.processInfo.environment["PHOTATO_TEST_CAPTURE_DIR"]{let dir=URL(fileURLWithPath:path);try FileManager.default.createDirectory(at:dir,withIntermediateDirectories:true);try JSONSerialization.data(withJSONObject:["width":20,"height":16,"rows":rows],options:.sortedKeys).write(to:dir.appendingPathComponent("layer-links-move-analytical.json"))}
  }
